$totals=['present'=>0,'absent'=>0,'leave'=>0,'late_count'=>0];foreach($daily as $r)foreach($totals as $k=>$n)$totals[$k]+=$r[$k];?><div class="stats"><?php foreach(['present'=>'Present day equivalents','absent'=>'Absent day equivalents','leave'=>'Approved leave days','late_count'=>'Late arrivals'] as $key=>$label):?><section class="card"><p class="eyebrow"><?=h($label)?></p><h2><?=h($totals[$key])?></h2></section><?php endforeach;?></div>
