$edit=null;if(isset($_GET['edit'])&&can($pdo,$user,'attendance.manage')){$q=$pdo->prepare('SELECT * FROM hr_attendance WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch(PDO::FETCH_ASSOC)?:null;}$v=$error?$_POST:($edit?:['attendance_date'=>date('Y-m-d')]);
if(can($pdo,$user,'attendance.manage')):?><details class="card core-editor" <?=($edit||$error)?'open':''?>><summary><?=$edit?'Correct attendance / add check-out':'Record check-in / attendance'?></summary><form method="post" class="form-grid core-form"><?php ftoken();chr_hidden('action','core_attendance');chr_hidden('id',$edit['id']??0);chr_hidden('version',$edit['version']??0);chr_select('employee_id','Employee',$v['employee_id']??'', [''=>'Select employee']+$employeeOptions);field('attendance_date','Attendance date',$v,'date',true);field('check_in','Check-in',$v,'datetime-local',true);field('check_out','Check-out (optional)',$v,'datetime-local');choose('source','Source',$v,['Admin','Manual','Web','eSSL','API']);field('notes','Correction reason / notes',$v,'text',(bool)$edit,3000);?><p class="full">Times use <?=h($company['timezone']??date_default_timezone_get())?>. For overnight work, enter the next date for check-out. Source labels record provenance; they do not connect a device.</p><div class="full"><button class="button primary">Save attendance</button> <a class="button" href="?page=<?=h($page)?>">Clear</a></div></form></details><?php endif;?>
<form method="get" class="card form-grid core-form"><?php chr_hidden('page',$page);if($page==='monthly')field('month','Month',$_GET+['month'=>date('Y-m')],'month',true);elseif($page==='attendance_history'){field('from','From',$_GET+['from'=>date('Y-m-01')],'date',true);field('to','To',$_GET+['to'=>date('Y-m-d')],'date',true);}else field('date','Date',$_GET+['date'=>date('Y-m-d')],'date',true);chr_select('employee_id','Employee',$_GET['employee_id']??'', [''=>'All employees']+$historyEmployeeOptions);chr_select('department_id','Department',$_GET['department_id']??'', [''=>'All departments']+$departmentOptions);chr_select('shift_id','Shift',$_GET['shift_id']??'', [''=>'All shifts']+$shiftOptions);if($page!=='monthly')chr_select('status','Status',$_GET['status']??'',array_combine(['','Present','Late','Absent','Open','Half Day','Half Day Leave','Leave','Holiday','Week Off','Unscheduled','Pending','Not started','Not active','Review needed'],['All statuses','Present','Late','Absent','Open','Half Day','Half Day Leave','Leave','Holiday','Week Off','Unscheduled','Pending','Not started','Not active','Review needed']));field('search','Search name or employee ID',$_GET);?><div class="full"><button class="button primary">Apply filters</button><?php if(can($pdo,$user,'attendance.reports')):?> <button class="button" name="export" value="1">Download CSV</button><?php endif;?></div></form>

<p>Past scheduled days without a punch or approved leave are absent. Today and future days remain pending. Unassigned shifts do not imply absence. Half-day leave and presence are counted separately; open punches need check-out.</p>
<section class="card"><div class="table-scroll attendance-table-scroll" tabindex="0" role="region" aria-label="Attendance report"><table class="directory"><thead><tr><th>Employee</th><th>ID / department</th><?php if($page==='monthly'):foreach(['Working days','Present','Absent','Leave','Paid leave','Unpaid leave','Holidays','Week offs','Late count','Half days','Worked','Overtime'] as $label):?><th><?=h($label)?></th><?php endforeach;else:foreach(['Date / shift','Check-in','Check-out','Worked','Late','Early','Overtime','Status','Source','Actions'] as $label):?><th><?=h($label)?></th><?php endforeach;endif;?></tr></thead><tbody><?php $number=max(1,(int)($_GET['p']??1));$shown=array_slice($rows,($number-1)*50,50);if(!$shown):?><tr><td colspan="13">No matching attendance.</td></tr><?php endif;foreach($shown as $r):?><tr><td><?=h($r['name'])?></td><td><?=h($r['employee_code']?:'Not assigned')?><small><?=h($r['department'])?></small></td><?php if($page==='monthly'):foreach(['working_days','present','absent','leave','paid_leave','unpaid_leave','holidays','week_offs','late_count','half_days','working_minutes','overtime_minutes'] as $key):?><td><?=h(str_ends_with($key,'minutes')?chr_hours($r[$key]):$r[$key])?></td><?php endforeach;else:?><td><?=h($r['date'])?><small><?=h($r['shift'])?></small></td><td><?=h($r['check_in']?:'—')?></td><td><?=h($r['check_out']?:'—')?></td><?php foreach(['working_minutes','late_minutes','early_minutes','overtime_minutes'] as $key):?><td><?=h(chr_hours($r[$key]))?></td><?php endforeach;?><td><?php fbadge($r['status'],!in_array($r['status'],['Absent','Open','Review needed'],true));?><small><?=h($r['note'])?></small></td><td><?=h($r['source'])?></td><td><?php if($r['record_id']&&can($pdo,$user,'attendance.manage')):?><a class="button" href="?page=attendance&date=<?=h($r['date'])?>&edit=<?=(int)$r['record_id']?>">Edit / check-out</a><?php endif;?></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><nav class="pagination" aria-label="Report pages"><?php for($i=max(1,$number-2);$i<=min((int)ceil(count($rows)/50),$number+2);$i++):?><a class="button" href="?<?=h(http_build_query(array_merge($_GET,['p'=>$i])))?>"><?=$i?></a><?php endfor;?></nav></section>

<?php if($user['role']==='super_admin'&&att_biometric_enabled($pdo)):?><p><a class="button" href="?page=device_attendance">Existing device punch reports</a> <a class="button" href="?page=raw_logs">Raw biometric logs</a> <a class="button" href="?page=sync">Sync history</a></p><p>Mapped biometric punches are automatically processed into daily attendance. Pending punches retry while the office bridge is running; manual attendance stays protected.</p><?php endif;?>
